"""Verify an extracted runtime and optionally emit exact path-relocated launch plans. This helper never runs Java."""

import argparse
import json
import os
from pathlib import Path
import shlex
import shutil
import tempfile

from runtime_bundle_io import (ROOT, PHASE, MANIFEST, file_hash, json_bytes, member_relative, path_under,
                               publish_no_replace, require, sha_bytes, validate_extracted)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--repo', type=Path, default=ROOT)
    parser.add_argument('--expected-manifest-sha256')
    parser.add_argument('--validate-only', action='store_true')
    parser.add_argument('--java', type=Path, help='Compatible local Java executable; existence is checked without execution')
    parser.add_argument('--output', type=Path, help='New derivative launch-plan directory outside the immutable extraction')
    args = parser.parse_args()
    repo = args.repo.resolve(strict=True)
    require(args.validate_only != bool(args.output), 'Choose --validate-only or --output')
    manifest, manifest_hash = validate_extracted(repo, args.expected_manifest_sha256)
    validation = {'format': 1, 'bundleManifestSha256': manifest_hash,
                  'acceptedTimingComparison': False,
                  'verifiedFiles': len(manifest['files']), 'verifiedRuntimeArtifacts': len(manifest['runtimeArtifacts']),
                  'verifiedRuntimes': len(manifest['runtimes']), 'verifiedRecordedCommands': len(manifest['commands']),
                  'primaryStudyStatus': manifest['primaryStudyStatus'],
                  'javaExecuted': False, 'originalBundleBytesUnchanged': True}
    if args.validate_only:
        print(json.dumps(validation, indent=2))
        return
    require(args.java is not None, '--java is required when generating launch plans')
    java = args.java.resolve(strict=True)
    require(java.is_file() and os.access(java, os.X_OK), 'Java path must be an executable regular file')
    output = args.output.parent.resolve(strict=True) / args.output.name
    require(not output.exists() and not output.is_relative_to(repo), 'Launch-plan output must be new and outside extraction')
    require(os.pathsep not in str(repo) and '\n' not in str(repo), 'Extraction path is not classpath-safe')
    artifacts = {artifact['path']: artifact for artifact in manifest['runtimeArtifacts']}
    mapping = {artifact['originalAbsolutePath']: str(path_under(repo, member_relative(path)))
               for path, artifact in artifacts.items()}
    products, runtime_plans = {}, {}
    for name, runtime in manifest['runtimes'].items():
        entries = [original | {'path': mapping[original['path']]} for original in runtime['originalManifest']]
        cp = os.pathsep.join(entry['path'] for entry in entries)
        runtime_plans[name] = {'sourceIdentity': runtime['sourceIdentity'], 'classpath': cp, 'manifest': entries,
                               'originalDescriptorPreserved': runtime['descriptor']}
        products['runtimes/' + name + '/classpath.txt'] = (cp + '\n').encode()
        products['runtimes/' + name + '/classpath-manifest.json'] = json_bytes(entries)
        products['runtimes/' + name + '/relocated-runtime.json'] = json_bytes(runtime_plans[name])
    commands = []
    shell_groups = {'primary': [], 'page-diagnostic': [], 'resolver-diagnostic': []}
    for record in manifest['commands']:
        before = record['originalArgv']
        after = list(before)
        after[0] = str(java)
        cp_index = after.index('-cp') + 1
        after[cp_index] = runtime_plans[record['runtime']]['classpath']
        run_output = output / 'runs' / record['label']
        required_directories = [str(run_output)]
        changes = [{'argument': 0, 'purpose': 'local compatible JDK'},
                   {'argument': cp_index, 'purpose': 'verified classpath path mapping'}]
        for i, argument in enumerate(before):
            if argument.startswith('--output='):
                after[i] = '--output=' + str(run_output / 'samples.jsonl')
                changes.append({'argument': i, 'purpose': 'new result output'})
            elif argument.startswith('--store='):
                after[i] = '--store=' + str(run_output / 'store')
                changes.append({'argument': i, 'purpose': 'fresh regenerated store'})
            elif argument.startswith('-Drdf4j.lmdb.publicationDiagnostic.output='):
                path = str(run_output / 'page-records')
                after[i] = '-Drdf4j.lmdb.publicationDiagnostic.output=' + path
                required_directories.append(path)
                changes.append({'argument': i, 'purpose': 'new diagnostic record output'})
            elif argument.startswith('-Xlog:'):
                prefix = '-Xlog:gc*,gc+ref=debug:file='
                require(argument.startswith(prefix), 'Unexpected GC logging argument')
                original_file, separator, suffix = argument[len(prefix):].partition(':')
                require(separator and Path(original_file).name == 'gc.log'
                        and suffix == 'time,uptime,level,tags:filecount=0', 'Unexpected GC log output/options')
                after[i] = prefix + str(run_output / 'gc.log') + ':' + suffix
                changes.append({'argument': i, 'purpose': 'new unrotated GC/reference log output'})
        require(record['schema'] == 'query-harness', 'Unexpected command schema')
        require(sum(arg.startswith('--output=') for arg in before) == 1
                and sum(arg.startswith('--store=') for arg in before) == 1,
                'Every query harness must have exactly one output and store')
        diagnostic_count = sum(arg.startswith('-Drdf4j.lmdb.publicationDiagnostic.output=') for arg in before)
        require(diagnostic_count == (1 if record['purpose'] in {'page-diagnostic', 'resolver-diagnostic'} else 0),
                'Diagnostic output property differs from command purpose')
        require(sum(argument.startswith('-Xlog:') for argument in before)
                == (1 if record['purpose'] == 'resolver-diagnostic' else 0),
                'GC/reference logging differs from the recorded diagnostic purpose')
        changed = {item['argument'] for item in changes}
        require(all(a == b for i, (a, b) in enumerate(zip(before, after)) if i not in changed),
                'Relocation changed a non-path argument')
        command = record | {'argv': after, 'cwd': str(repo), 'outputDirectory': str(run_output),
                            'requiredDirectories': required_directories, 'pathOnlyChanges': changes}
        commands.append(command)
        command_relative = 'commands/' + record['label'] + '.json'
        products[command_relative] = json_bytes(command)
        lines = ['mkdir -- ' + shlex.quote(str(run_output)),
                 'cp -- ' + shlex.quote(str(output / command_relative)) + ' ' + shlex.quote(str(run_output / 'command.json'))]
        lines += ['mkdir -- ' + shlex.quote(path) for path in required_directories[1:]]
        lines += [shlex.join(after) + ' >' + shlex.quote(str(run_output / 'console.log')) + ' 2>&1']
        shell_groups[record['purpose']] += lines
    guard = '''#!/usr/bin/env bash
set -euo pipefail
for name in JAVA_TOOL_OPTIONS JDK_JAVA_OPTIONS _JAVA_OPTIONS; do
  if [[ -v "$name" ]]; then
    echo "Unexpected injected Java option variable: $name" >&2
    exit 2
  fi
done
'''
    preamble = guard + 'cd -- ' + shlex.quote(str(repo)) + '\n'
    for group, lines in shell_groups.items():
        products['run-' + group + '-commands.sh'] = (preamble + '\n'.join(lines) + '\n').encode()
    products['launch-plan.json'] = json_bytes({'format': 1, 'bundleManifestSha256': manifest_hash,
        'runtimePathMapping': mapping, 'runtimes': runtime_plans, 'commands': commands,
        'javaExecutable': str(java), 'jdkVersionNotExecutedByRelocation': True,
        'expectedJavaVersion': '25.0.5+8-LTS', 'expectedHeapBytes': 1073741824,
        'primaryStudyStatus': manifest['primaryStudyStatus'], 'acceptedTimingComparison': False,
        'targetedDiagnosticStudies': manifest.get('targetedDiagnosticStudies', []),
        'resultsRequireTheirOriginalCorrectnessRouteAndMetadataChecks': True})
    products['verification.json'] = json_bytes(validation)
    primary_count = sum(command['purpose'] == 'primary' for command in commands)
    diagnostic_count = sum(command['purpose'] == 'page-diagnostic' for command in commands)
    resolver_count = sum(command['purpose'] == 'resolver-diagnostic' for command in commands)
    products['README.md'] = (f'''# Verified relocated publication-ablation commands

All bundled files, artifact hashes and runtime/command bindings were verified before this plan was generated.
The extracted original evidence and protocols remain byte-for-byte unchanged. The derivative classpaths and commands
change only the Java executable, artifact paths, working directory, fresh store paths and output paths. The fixture
masks, all JVM/configuration options and the original source identities remain exact.

Use the matching Eclipse Adoptium JDK 25.0.5+8 and recorded JVM arguments. JDK/operating-system installation is
outside the bundle. This helper checked that the chosen Java executable exists; it did not run it.

The original fixed primary study stopped after {primary_count} of 36 planned JVMs: 117 queries and 45 measurements.
It remains incomplete, with no accepted timing ratios. The failed warmup resolver-equality gate, all raw records and
the original stop error are retained. No replacement runs, exclusions, lower gate or extra timing rounds are supplied.

`run-primary-commands.sh` contains only the {primary_count} recorded commands, in the captured prefix of the prescribed
schedule. These are inspection launch plans; executing them neither resumes nor qualifies the stopped experiment.
Do not overlap them with builds, profiling, hashing, compression or other benchmarks. The separate
`run-page-diagnostic-commands.sh` contains {diagnostic_count} instrumented fixture runs, including their original
512 MiB or 256 MiB per-query budgets. Diagnostic durations and allocations do not estimate performance. The scripts
refuse existing run directories and stop on the first process failure. They do not retry failed forks or implement
the original driver's per-query acceptance/stop logic. The original protocols and validators remain the authority.

`run-resolver-diagnostic-commands.sh` contains {resolver_count} separately declared cause-investigation commands, when
present. Their GC/reference logs, mask settings, query counts and command order remain prescribed by their own frozen
protocol. These commands cannot replace the stopped primary forks or qualify timing comparisons.

Commands regenerate their own graph/store. Original commands, complete experimental Java, source identities, raw
results and validators are included under `result-coordinate-evidence/publication-followup/`. Passing a Java process
is not itself evidence of a valid new comparison: retain every query, validate the result bag/checksum, ledger,
route/tier, resolver, adjacency and JVM metadata gates, and apply the original predeclared analysis. These scripts do
not accept or rank new performance results. They are launch plans; original validators still retain source-workspace
path and analysis-directory conventions. This relocation receipt does not qualify future rerun results.

The selected production materializer remains the original. The name-mask overlay is an experimental counterfactual,
not a production selection. Its mask metadata is common across arms and is outside the query ledger. Original nested
page/memo class bytes stay in the timing runtime; discarded emitted classes are preserved separately as provenance.

This relocation performed no Java, build, test or benchmark operation.
''').encode()
    staging = Path(tempfile.mkdtemp(prefix='.publication-runtime-relocation-', dir=output.parent))
    published = False
    try:
        for relative, content in products.items():
            destination = staging / relative
            destination.parent.mkdir(parents=True, exist_ok=True)
            destination.write_bytes(content)
            if relative.endswith('.sh'):
                destination.chmod(0o755)
        (staging / 'runs').mkdir()
        (staging / 'SHA256SUMS').write_text(''.join(sha_bytes(content) + '  ' + relative + '\n'
                                                  for relative, content in sorted(products.items())))
        publish_no_replace(staging, output)
        published = True
        print(json.dumps(validation | {'relocatedPlan': str(output), 'pathMappedCommands': len(commands)}, indent=2))
    finally:
        if not published:
            shutil.rmtree(staging)


if __name__ == '__main__':
    main()
